-- =====================================================================
-- خلاصه پوشش (برای بررسی دستی)
-- =====================================================================
SELECT 'companies' AS tbl, COUNT(*) AS n FROM companies WHERE name LIKE '%ماتریس تست%'
UNION ALL SELECT 'projects (TM-%)', COUNT(*) FROM projects WHERE code LIKE 'TM-%'
UNION ALL SELECT 'users (tm_*)', COUNT(*) FROM users WHERE username LIKE 'tm\_%'
UNION ALL SELECT 'user_projects', COUNT(*) FROM user_projects
UNION ALL SELECT 'kahta_accounts', COUNT(*) FROM kahta_accounts WHERE project_id IN (SELECT id FROM projects WHERE code LIKE 'TM-%')
UNION ALL SELECT 'money_receipts', COUNT(*) FROM money_receipts WHERE project_id IN (SELECT id FROM projects WHERE code LIKE 'TM-%')
UNION ALL SELECT 'expenses', COUNT(*) FROM expenses WHERE project_id IN (SELECT id FROM projects WHERE code LIKE 'TM-%')
UNION ALL SELECT 'kahta_advances', COUNT(*) FROM kahta_advances WHERE project_id IN (SELECT id FROM projects WHERE code LIKE 'TM-%')
UNION ALL SELECT 'revenue_to_sarafi', COUNT(*) FROM revenue_to_sarafi WHERE project_id IN (SELECT id FROM projects WHERE code LIKE 'TM-%')
UNION ALL SELECT 'customers', COUNT(*) FROM customers WHERE project_id IN (SELECT id FROM projects WHERE code LIKE 'TM-%')
UNION ALL SELECT 'contracts', COUNT(*) FROM contracts WHERE project_id IN (SELECT id FROM projects WHERE code LIKE 'TM-%')
UNION ALL SELECT 'machinery', COUNT(*) FROM machinery WHERE project_id IN (SELECT id FROM projects WHERE code LIKE 'TM-%')
UNION ALL SELECT 'employees', COUNT(*) FROM employees WHERE project_id IN (SELECT id FROM projects WHERE code LIKE 'TM-%')
UNION ALL SELECT 'employee_attendance', COUNT(*) FROM employee_attendance WHERE project_id IN (SELECT id FROM projects WHERE code LIKE 'TM-%')
UNION ALL SELECT 'employee_leaves', COUNT(*) FROM employee_leaves WHERE project_id IN (SELECT id FROM projects WHERE code LIKE 'TM-%')
UNION ALL SELECT 'audit_log', COUNT(*) FROM audit_log;

-- =====================================================================
-- CLEANUP — پاک‌سازی کامل ماتریس تست (در صورت نیاز، کامنت‌ها را بردارید)
-- حذف شرکت‌ها به‌صورت زنجیره‌ای پروژه‌ها و تمام داده‌های مالی/پروژه‌ای را
-- پاک می‌کند. کاربران باید جداگانه حذف شوند (company_id آن‌ها NULL می‌شود).
-- =====================================================================
-- DELETE FROM users WHERE username LIKE 'tm\_%';
-- DELETE FROM user_projects WHERE user_id NOT IN (SELECT id FROM users);
-- DELETE FROM audit_log WHERE username LIKE 'tm\_%' OR username = 'admin';
-- DELETE FROM companies WHERE name LIKE '%ماتریس تست%';

